INSERT INTO `sedes` (`id`, `nombre`, `direccion`, `telefono`, `estado`, `created_at`, `updated_at`) VALUES ('01a0f2e8-edfa-72d5-923c-ee0c142bf008', 'CATA Oasis', NULL, NULL, 'activo', '2026-09-30 10:22:26', '2026-10-01 15:33:22');
INSERT INTO `sedes` (`id`, `nombre`, `direccion`, `telefono`, `estado`, `created_at`, `updated_at`) VALUES ('01a0f2e8-ee0b-728b-821c-3f435bf37ba3', 'CATA Inicial', NULL, NULL, 'activo', '2026-09-30 10:22:26', '2026-09-30 10:22:26');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e528-73e1-ac5d-428fbd89bd39', 'Remuneración Básica', NULL, 'bonificacion', NULL, NULL, 'El sueldo del mes. NO se agrega como línea: sale de la ficha del trabajador y la boleta lo imprime en su propia fila. Está en el catálogo para que se vea completo.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e6ba-7228-a3ae-4f776393ae34', 'Bonificación por Cargo', NULL, 'bonificacion', NULL, NULL, 'Lo que se le paga de más por el puesto que ocupa (coordinación, jefatura). El monto es de cada quien, así que se agrega caso por caso.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e6d0-700d-818d-7003a9d72ca2', 'Asignación Familiar', NULL, 'bonificacion', 'fijo', '113.00', 'El 10% de la RMV para quien tiene hijos menores de 18, o hasta 24 si siguen estudiando. Lo calcula el sistema mirando \"tiene hijos\" en su ficha.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e6e0-71bd-8e42-1f00ac8d442b', 'Vacaciones Truncas', NULL, 'bonificacion', NULL, NULL, 'Un doceavo del sueldo por cada mes completo trabajado, de las vacaciones ganadas y no tomadas. Es la vía de plazo fijo, suplencia y prácticas: ellos no piden descanso, se les paga con este concepto.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e6f3-7028-b022-e4302a2efe99', 'Gratificaciones Fiestas Patrias - Ley 29351 y 30334', 'Gratificación', 'bonificacion', NULL, NULL, 'La gratificación de julio y la de diciembre. Es un sueldo completo si trabajó el semestre entero, o la parte proporcional a los meses que sí trabajó. La planilla la crea sola en esos dos meses.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e702-70a8-aff1-0a8aa315907e', 'Bonif. Extraord. Temporal - Ley 29351 y 30334', 'Bonificación Extraordinaria (Ley 30334, 9%)', 'bonificacion', 'porcentaje', '9.00', 'El 9% de la gratificación: es el aporte a EsSalud que la ley ordena entregarle al trabajador en vez de retenerlo. Solo sale en los meses con gratificación.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e713-70df-8cdd-13f4e5a8a41f', 'Bonificaciones', NULL, 'bonificacion', NULL, NULL, 'Bonificación general, distinta de la de cargo y de la extraordinaria. Para lo que el colegio otorgue sin una regla fija.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e726-70c6-852d-f0af0ab31392', 'Compensación por Tiempo de Servicios', NULL, 'bonificacion', NULL, NULL, 'La CTS. Normalmente se deposita en su cuenta en mayo y noviembre; acá solo aparece cuando se le paga junto con la boleta.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e74c-708d-9883-b69cb913361e', 'Planilla de Movilidad', NULL, 'bonificacion', NULL, NULL, 'Lo que se le paga por movilizarse por trabajo. Va aparte del sueldo y el monto es de cada quien, así que se agrega caso por caso.', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e75f-70a9-b606-f8ec070f0786', 'Otros Conceptos (Ingresos)', 'Otros Conceptos', 'bonificacion', NULL, NULL, 'La bolsa para un ingreso puntual de UNA persona: subsidio de maternidad, reintegro, movilidad de un viaje. Se escribe el detalle al agregarlo y la boleta imprime \"Otros Conceptos: Subsidio de Maternidad\".', 0, '2026-09-30 10:22:24', '2026-09-30 10:22:24');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e770-7365-8e4f-93243552f7a3', 'ONP 13%', NULL, 'descuento', 'porcentaje', '13.00', 'El aporte a la ONP. Solo para quien está en el Sistema Nacional; lo calcula el sistema sobre el sueldo más la asignación familiar.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e77b-739e-9222-53ddc92365a7', 'SPP. Fondo Pensiones', NULL, 'descuento', 'porcentaje', '10.00', 'El aporte obligatorio a la AFP: el 10% que se va a su fondo de jubilación. Solo para quien está en una AFP.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e789-7310-8ae3-87ad9d004985', 'SPP. Prima de Seguro', NULL, 'descuento', 'porcentaje', '1.37', 'La prima del seguro de invalidez y sobrevivencia, igual para todas las AFP. Lo calcula el sistema.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e796-7160-8b2b-f31703f91b9d', 'SPP. Comisión', NULL, 'descuento', 'porcentaje', NULL, 'La comisión que cobra su AFP y que cambia según cuál sea (Habitat 1.47, Integra 1.55, Prima 1.60, Profuturo 1.69). No tiene un valor fijo acá: lo pone el sistema según su ficha.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e7d7-704f-b945-599633ae22ff', 'I.R. 5ta Categoría', NULL, 'descuento', NULL, NULL, 'La retención de quinta categoría. No es un porcentaje fijo: se calcula por tramos sobre lo que va a ganar en el año y descontando lo ya retenido, así que solo le sale a quien pasa las 7 UIT.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e7ed-7110-989a-ecefdc6a9228', 'Descuento Serv. Alimentación', NULL, 'descuento', NULL, NULL, 'Lo que consumió en el comedor del colegio y se le descuenta del sueldo.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e7fb-73c0-a57e-41c279a42c27', 'Descuento Autorizado - Diezmo', NULL, 'descuento', 'porcentaje', '10.00', 'El 10% del sueldo básico que se entrega a la iglesia. Se le pone solo a todo el personal. A quien no lo autorice, quítale la línea desde su detalle.', 1, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e804-7341-8b70-dce433b3e8b0', 'Descuento - Pago de Escolaridad Mensual', NULL, 'descuento', NULL, NULL, 'La pensión de sus hijos estudiando en el colegio, descontada del sueldo en vez de pagarla en caja.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e81c-7366-ab94-58ebbc7621d9', 'Descuento Serv. Bazar', NULL, 'descuento', NULL, NULL, 'Lo que se llevó del bazar del colegio y se le descuenta del sueldo.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e830-70a7-b418-c91aee222d7d', 'Descuento Serv. Copias', NULL, 'descuento', NULL, NULL, 'Las copias e impresiones que se le hicieron en el colegio y se le descuentan del sueldo.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e83a-70f4-855d-5e218eddcaf0', 'Descuento Autorizado - Tardanzas y Faltas', NULL, 'descuento', NULL, NULL, 'Lo que se le descuenta por llegar tarde o faltar. El monto se saca de sus minutos de tardanza y de su pago por hora, así que se agrega caso por caso.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e84d-71b5-910e-7bef91771f2b', 'Otros Conceptos (Descuentos)', 'Otros Conceptos', 'descuento', NULL, NULL, 'La bolsa para un descuento puntual de UNA persona: un préstamo, una tardanza, un material que se le entregó. Se escribe el detalle al agregarlo y la boleta imprime \"Otros Conceptos: Préstamo\".', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e85b-72dd-80e0-934bafc3b496', 'ESSALUD 9%', NULL, 'aportacion', 'porcentaje', '9.00', 'El 9% que el colegio aporta por cada trabajador para su seguro de salud. No sale de su sueldo: se imprime para que sepa cuánto se paga por él.', 1, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e86f-73e0-999c-fa92d05e1d95', 'SCTR', NULL, 'aportacion', NULL, NULL, 'Seguro Complementario de Trabajo de Riesgo, para los puestos que la ley considera riesgosos. La tasa depende de la actividad y de la aseguradora contratada.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e885-7385-ae29-e4a779ff0b60', 'Adelanto de Sueldo', NULL, 'adelanto', NULL, NULL, 'Dinero del sueldo del mes que se le entregó por adelantado. Se le resta del neto al pagar.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
INSERT INTO `payment_concepts` (`id`, `nombre`, `etiqueta_boleta`, `tipo`, `calculo`, `valor`, `descripcion`, `aplica_a_todos`, `created_at`, `updated_at`) VALUES ('01a0f2e8-e8a5-7330-ac81-9bf6fded3191', 'Adelanto de Bonificaciones', NULL, 'adelanto', NULL, NULL, 'Igual que el anterior, pero sobre una bonificación o gratificación que todavía no tocaba pagar.', 0, '2026-09-30 10:22:25', '2026-09-30 10:22:25');
